// 生成勇士游戏随机分数
function generateRandomScore() {
    const min = 1000;
    const max = 4000;
    const randomScore = Math.floor(Math.random() * (max - min + 1)) + min;

    // 新增：生成随机秒数
    const minSeconds = 1000;
    const maxSeconds = 10000;
    const randomSeconds = Math.floor(Math.random() * (maxSeconds - minSeconds + 1)) + minSeconds;

    // 调用处理函数，传入随机分数和随机秒数
    handleMiniGameButtonClick(randomScore, randomSeconds);
}

// 生成数独游戏得分
function generateSudokuScore() {
    const level = document.getElementById('mini-sudoku-level').value;
    const value = document.getElementById('mini-sudoku-value').value;
    const min = 9;
    const max = 12;
    const randomValue = (Math.floor(Math.random() * (max - min + 1)) + min) * 60 * 1000;

    handleSudokuGameButtonClick(level, value, randomValue);
}

// 生成奇妙魔石游戏得分
function generateStoneScore() {
    const level = document.getElementById('mini-stone-level').value;
    const value = document.getElementById('mini-stone-value').value;
    const min = 50;
    const max = 100;
    const randomValue = Math.floor(Math.random() * (max - min + 1)) + min;

    handleStoneGameButtonClick(level, value, randomValue);
}

